  ('babymonster-q115967938', array[
    'BABYMONSTER는 루카, 파리타, 아사, 아현, 라미, 로라, 치키타로 구성된 YG Entertainment의 걸 그룹입니다. 강한 힙합 기반 퍼포먼스와 보컬·랩 역량, 다국적 멤버의 개성을 함께 보여 줍니다.',
    '프리 데뷔 과정과 ‘BATTER UP’을 거쳐 7인 완전체 앨범 《BABYMONS7ER》로 공식 활동을 시작했고, 정규 앨범 《DRIP》과 후속 프로젝트로 글로벌 활동을 확대하고 있습니다.'
  ], '[{"year":"2023","text":"‘BATTER UP’을 공개하며 프리 데뷔 활동 시작.","source_url":"https://ygfamily.com/en/artists/babymonster/profile"},{"year":"2024","text":"7인 완전체 미니 앨범 《BABYMONS7ER》와 ‘SHEESH’로 공식 데뷔.","source_url":"https://ygfamily.com/en/artists/babymonster/discography"},{"year":"2024","text":"첫 정규 앨범 《DRIP》 발표.","source_url":"https://ygfamily.com/en/artists/babymonster/discography"},{"year":"2025","text":"미니 앨범 《WE GO UP》으로 활동 확장.","source_url":"https://ygfamily.com/en/artists/babymonster/discography"},{"year":"2026","text":"프로젝트 《춤 (CHOOM)》을 발표하며 퍼포먼스 색을 이어감.","source_url":"https://ygfamily.com/en/artists/babymonster/discography"}]'::jsonb,
  '[{"year":"2024","text":"MAMA Awards Fans’ Choice Female 수상.","source_url":"https://en.wikipedia.org/wiki/List_of_awards_and_nominations_received_by_Babymonster"},{"year":"2024","text":"The Fact Music Awards Next Leader상 수상.","source_url":"https://en.wikipedia.org/wiki/List_of_awards_and_nominations_received_by_Babymonster"},{"year":"2025","text":"Golden Disc Awards Rookie Artist of the Year 수상.","source_url":"https://en.wikipedia.org/wiki/List_of_awards_and_nominations_received_by_Babymonster"}]'::jsonb),

  ('zerobaseone-q117808633', array[
    'ZEROBASEONE은 Mnet 《BOYS PLANET》을 통해 결성된 보이 그룹입니다. 청춘의 시작과 성장, 팬덤 ZEROSE와 함께 완성하는 여정을 밝고 섬세한 음악과 퍼포먼스로 표현합니다.',
    '데뷔 앨범 《YOUTH IN THE SHADE》부터 《MELTING POINT》, 《You had me at HELLO》, 《BLUE PARADISE》까지 연속적인 앨범 서사를 전개하며 한국과 일본에서 활발히 활동했습니다.'
  ], '[{"year":"2023","text":"《BOYS PLANET》 최종회를 통해 멤버를 확정.","source_url":"https://en.wikipedia.org/wiki/ZeroBaseOne"},{"year":"2023","text":"미니 앨범 《YOUTH IN THE SHADE》와 ‘In Bloom’으로 데뷔.","source_url":"https://en.wikipedia.org/wiki/Youth_in_the_Shade"},{"year":"2023","text":"두 번째 미니 앨범 《MELTING POINT》 발표.","source_url":"https://en.wikipedia.org/wiki/ZeroBaseOne"},{"year":"2024","text":"《You had me at HELLO》와 일본 싱글로 활동 범위 확대.","source_url":"https://en.wikipedia.org/wiki/ZeroBaseOne_discography"},{"year":"2025","text":"《BLUE PARADISE》로 앨범 활동을 이어감.","source_url":"https://en.wikipedia.org/wiki/ZeroBaseOne_discography"}]'::jsonb,
  '[{"year":"2023","text":"MAMA Awards Best New Male Artist 수상.","source_url":"https://en.wikipedia.org/wiki/List_of_awards_and_nominations_received_by_ZeroBaseOne"},{"year":"2023","text":"Melon Music Awards New Artist of the Year 수상.","source_url":"https://en.wikipedia.org/wiki/List_of_awards_and_nominations_received_by_ZeroBaseOne"},{"year":"2024","text":"Golden Disc Awards Rookie Artist of the Year 수상.","source_url":"https://en.wikipedia.org/wiki/List_of_awards_and_nominations_received_by_ZeroBaseOne"},{"year":"2024","text":"MAMA Awards Worldwide Fans’ Choice 수상.","source_url":"https://en.wikipedia.org/wiki/List_of_awards_and_nominations_received_by_ZeroBaseOne"}]'::jsonb),

  ('nct-127-q55624444', array[
    'NCT 127은 서울의 경도 127을 팀명에 담은 NCT의 고정 유닛입니다. 네오한 전자음과 힙합, 실험적인 곡 구조, 강도 높은 퍼포먼스를 중심으로 서울에서 세계로 뻗어가는 팀의 정체성을 표현합니다.',
    '‘Cherry Bomb’, ‘Kick It’, ‘Sticker’, ‘2 Baddies’, ‘Fact Check’, ‘Walk’ 등 개성 강한 대표곡을 쌓았으며 한국·일본·북미 투어와 멤버별 활동을 병행하고 있습니다.'
  ], '[{"year":"2016","text":"미니 앨범 《NCT #127》과 ‘Fire Truck’으로 데뷔.","source_url":"https://en.wikipedia.org/wiki/NCT_127"},{"year":"2017","text":"《LIMITLESS》와 《CHERRY BOMB》으로 음악 색을 확립.","source_url":"https://en.wikipedia.org/wiki/NCT_127_discography"},{"year":"2020","text":"정규 2집 《Neo Zone》과 ‘Kick It’으로 글로벌 성과 확대.","source_url":"https://en.wikipedia.org/wiki/Neo_Zone"},{"year":"2021","text":"정규 3집 《Sticker》가 트리플 밀리언셀러 기록.","source_url":"https://en.wikipedia.org/wiki/Sticker_(album)"},{"year":"2024","text":"정규 6집 《WALK》와 ‘삐그덕’을 발표.","source_url":"https://en.wikipedia.org/wiki/NCT_127_discography"}]'::jsonb,
  '[{"year":"2017","text":"MAMA Awards New Asian Artist 수상.","source_url":"https://en.wikipedia.org/wiki/List_of_awards_and_nominations_received_by_NCT_127"},{"year":"2021","text":"MAMA Awards Worldwide Fans’ Choice 수상.","source_url":"https://en.wikipedia.org/wiki/List_of_awards_and_nominations_received_by_NCT_127"},{"year":"2022","text":"Seoul Music Awards 대상 수상.","source_url":"https://en.wikipedia.org/wiki/List_of_awards_and_nominations_received_by_NCT_127"},{"year":"2023","text":"Circle Chart Music Awards 월드 한류 스타상 수상.","source_url":"https://en.wikipedia.org/wiki/List_of_awards_and_nominations_received_by_NCT_127"}]'::jsonb)
)
update public.artists artist
set bio_paragraphs = enriched.bio_paragraphs || coalesce(artist.bio_paragraphs, '{}'::text[]),
    history_items = enriched.history_items || coalesce(artist.history_items, '[]'::jsonb),
    award_items = enriched.award_items || coalesce(artist.award_items, '[]'::jsonb),
    updated_at = now()
from enriched
where artist.slug = enriched.slug;

do $$
declare
  enriched_count integer;
begin
  select count(*) into enriched_count
  from public.artists
  where active = true
    and cardinality(bio_paragraphs) >= 2
    and jsonb_array_length(history_items) >= 4
    and jsonb_array_length(award_items) >= 3;

  if enriched_count <> 20 then
    raise exception 'Expected 20 enriched artists, found %', enriched_count;
  end if;
end
$$;
